import {esc} from './ui.js';import {renderTrend} from './charts.js';import {importClient} from './import-api.js';
const fmt=x=>x==null?'待补齐':new Intl.NumberFormat('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(x));
export function renderImportedVariance(items){const max=Math.max(1,...items.map(x=>Math.abs(x.delta??0)));return `<div class="variance-bars">${items.map(x=>`<div class="variance-row"><span>${esc(x.name)}</span><div class="bar-track"><div class="bar-fill ${x.delta>0?'red':'green'}" style="width:${Math.abs(x.delta??0)/max*100}%"></div></div><strong class="${x.delta>0?'negative':x.delta<0?'positive':''}">${x.delta===null?'待补齐':(x.delta>0?'+':x.delta<0?'−':'')+'¥'+fmt(Math.abs(x.delta))}</strong></div>`).join('')}</div>`;}
const pct=x=>x==null?'—':(Number(x)*100).toFixed(1)+'%';
const stateText={complete:'资料完整',provisional:'含暂估资料',incomplete:'生产或成本待补齐',operating_incomplete:'经营费用待补齐',not_started:'尚未开工'};
const source=r=>`${r.source?.sheet||''}!${r.source?.cell||''} · ${r.id||''}`;
const table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v??'待补齐')}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">当日没有可见记录。</td></tr>`}</tbody></table></div>`;
const option=(v,label,selected)=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(label)}</option>`;
const card=(title,value,note)=>`<article class="stat-card"><div class="stat-top"><span>${title}</span></div><div class="stat-value">${value}</div><p class="stat-foot">${note}</p></article>`;
const offset=(date,n)=>{const d=new Date(date+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);};
export function mountImported(root,{orderId,client=importClient}={}){
 let alive=true,seq=0,orders=[],selected=null,revision='',revisions=[],date='',mode='ideal',analysis=null,points=[],portfolio=null,tab='production';
 const status=()=>root.querySelector('#imported-status');
 const renderDetails=()=>{
  const rows=analysis?.daily?.rows??{production:[],materials:[],expenses:[],supplements:[]};
  if(tab==='production')return table(['日期','码号','加工量','不良量','合格量','来源'],rows.production.map(r=>[r.date,r.size,r.processed,r.defects,r.processed===null||r.defects===null?null:Number(r.processed)-Number(r.defects),source(r)]));
  if(tab==='materials')return table(['材料编号','净耗kg','单价元/kg','资料状态','来源'],rows.materials.map(r=>[r.materialId,r.net,r.price,r.status,source(r)]));
  if(tab==='expenses')return table(['类别','项目','实际金额元','资料状态','来源'],rows.expenses.map(r=>[r.category,r.item,fmt(r.amount),r.status,source(r)]));
  return table(['码号','补产数量','关联生产记录','计入方式','来源'],rows.supplements.map(r=>[r.size,r.quantity,r.parentId,'已含加工和净耗，不另追加',source(r)]));
 };
 function render(){
  if(!alive||!analysis)return;const a=analysis,c=a.cumulative,meaning=mode==='ideal'?'理想上界':'含损耗预算基线';
  const labels={materialPrice:'材料价格影响',materialUsage:'材料耗用影响',labor:'人工影响',energy:'能源影响',otherManufacturing:'其他制造影响',otherProduction:'其他生产影响',budgetAdjustment:'预算允许损耗',rounding:'舍入调整'};
  const bars=Object.entries(a.bridge.components).filter(([k,v])=>k!=='budgetAdjustment'||mode==='budget'||Number(v)!==0).map(([k,v])=>({name:labels[k],delta:v===null?null:Number(v)}));
  root.innerHTML=`<section class="panel imported-controls"><label>订单<select id="imported-order" class="control">${orders.map(o=>option(o.id,`${o.id} · ${o.product}`,selected.id)).join('')}</select></label><label>资料版本<select id="imported-revision" class="control">${revisions.map(r=>option(r.revisionId,r.revisionId,revision)).join('')}</select></label><label>对照基线<select id="imported-mode" class="control">${option('ideal','无额外损耗理想上界',mode)}${option('budget','含损耗预算的预期利润',mode)}</select></label><div class="imported-date"><button class="button" id="imported-prev" ${date<=a.order.start?'disabled':''}>上一天</button><input class="control" id="imported-date" type="date" aria-label="模拟截至日期" min="${esc(a.order.start)}" max="${esc(a.order.end)}" value="${esc(date)}"><button class="button" id="imported-next" ${date>=a.order.end?'disabled':''}>下一天</button></div></section><div class="imported-context"><span class="demo-pill">${a.order.isDemo?'模拟案例':'导入资料'}</span><span>${esc(stateText[a.quality.state])}</span><span>${esc(a.order.incomeBasis)} · ${esc(a.order.taxBasis)}</span><span id="imported-status" role="status"></span></div><section class="stats-grid imported-stats">${card(mode==='ideal'?'整单理论最大生产毛利':'整单预算生产毛利',fmt(a.theoreticalTotal.gross),'固定目标 · '+meaning)}${card('累计实际生产毛利',fmt(c.actual.gross),'截至 '+date+' · 毛利率 '+pct(c.actual.margin))}${card('同进度理论生产毛利',fmt(c.expected.gross),'相同累计合格产量 · '+meaning)}${card('与同进度理论相比少赚',fmt(c.gap),'正数表示少赚 · 实际减理论 '+fmt(c.delta))}</section><section class="panel imported-summary"><div class="panel-head"><h2>生产进度与经营利润</h2><span>${esc(a.baselineId)}</span></div><div class="panel-body kv-grid"><div>累计合格量<strong>${c.quantity??'待补齐'} / ${esc(a.order.quantity)} 双</strong></div><div>完成进度<strong>${pct(c.progress)}</strong></div><div>剩余需求 / 超产<strong>${c.remaining??'—'} / ${c.overproduction??'—'} 双</strong></div><div>累计经营利润<strong>${fmt(c.actual.operating)} 元</strong></div><div>当日生产毛利<strong>${fmt(a.daily?.actual.gross)} 元</strong></div><div>当日合格量<strong>${a.daily?.quantity??'待补齐'} 双</strong></div></div><div class="panel-body note">按日期可见的原始记录核算，未来实际记录不进入曲线。当前为管理试算；未结算不显示最终实际利润。</div></section>${a.quality.missing.length?`<section class="panel imported-summary"><div class="panel-head"><h2>待补齐资料</h2></div>${table(['日期','项目','提示'],a.quality.missing.slice(0,100).map(x=>[x.date,x.field,x.detail]))}</section>`:''}<div class="imported-analysis-grid"><section class="panel"><div class="panel-head"><h2>累计生产毛利变化</h2><span class="muted">蓝线实际 · 虚线理论</span></div><div class="chart-wrap">${renderTrend(points.map(p=>({...p,actual:p.actual===null?null:Number(p.actual),expected:p.expected===null?null:Number(p.expected)}))).replaceAll('data-day=','data-import-day=')}</div><div class="panel-footer">截至 ${esc(date)} · 点击节点查看当天</div></section><section class="panel"><div class="panel-head"><h2>利润差距来源</h2><span class="muted">正值表示成本增加</span></div><div class="panel-body">${renderImportedVariance(bars)}<p class="footnote">各项合计 ${fmt(a.bridge.total)} 元。补单是耗用和人工的解释依据，不重复列为一笔损失。</p></div></section></div><section class="panel imported-summary"><div class="panel-head"><h2>${esc(date)} 原始记录与来源</h2><div class="table-tools">${[['production','生产'],['supplements','补单'],['materials','材料'],['expenses','费用']].map(([k,t])=>`<button class="button ${tab===k?'primary':''}" data-import-tab="${k}">${t}</button>`).join('')}</div></div>${renderDetails()}<div class="panel-footer">补单为已包含关联；改变日期可逐日核查。资料版本 ${esc(revision)}</div></section>${portfolio?`<section class="panel imported-summary"><div class="panel-head"><h2>同日已导入订单</h2><span class="muted">可比 ${portfolio.totals.comparable} 笔 · 排除 ${portfolio.totals.excluded} 笔</span></div><div class="panel-body">已知实际毛利 ${fmt(portfolio.totals.actualGross)} 元 · 可比范围少赚 ${fmt(portfolio.totals.gap)} 元</div>${table(['订单','累计合格双','累计实际毛利元','同进度差距元','资料状态'],portfolio.orders.map(r=>[r.order.id,r.cumulative.quantity,fmt(r.cumulative.actual.gross),fmt(r.cumulative.gap),stateText[r.quality.state]]))}</section>`:''}`;
  root.querySelector('#imported-date').addEventListener('change',e=>{if(!e.target.value||e.target.value<a.order.start||e.target.value>a.order.end){render();return;}date=e.target.value;load();});
  root.querySelector('#imported-prev').onclick=()=>{date=offset(date,-1);load();};root.querySelector('#imported-next').onclick=()=>{date=offset(date,1);load();};
  root.querySelector('#imported-mode').onchange=e=>{mode=e.target.value;load();};root.querySelector('#imported-revision').onchange=e=>{revision=e.target.value;load();};
  root.querySelector('#imported-order').onchange=e=>{location.hash='#imported/'+encodeURIComponent(e.target.value);};
  root.querySelectorAll('[data-import-tab]').forEach(btn=>btn.onclick=()=>{tab=btn.dataset.importTab;render();});
  root.querySelectorAll('[data-import-day]').forEach(el=>{const run=()=>{date=el.dataset.importDay;load();};el.onclick=run;el.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();run();}};});
 }
 async function load(){
  const request=++seq;if(status())status().textContent='正在核算…';
  try{const a=await client.getAnalysis(selected.id,{asOf:date,revision,baselineMode:mode});if(!alive||request!==seq)return;
   if(date<a.order.start||date>a.order.end){date=date<a.order.start?a.order.start:a.order.end;return load();}
   const [t,p]=await Promise.all([client.getTrend(selected.id,{start:a.order.start,end:date,revision,baselineMode:mode}),client.getPortfolio({asOf:date,baselineMode:mode})]);if(!alive||request!==seq)return;
   analysis=a;points=t.points;portfolio=p;render();
  }catch(e){if(alive&&request===seq){if(status())status().textContent=e.message;else root.innerHTML=`<section class="panel import-intro"><h2>数据载入失败</h2><p>${esc(e.message)}</p><a class="button" href="#import">返回导入</a></section>`;}}
 }
 root.innerHTML='<div class="loading">正在读取本地订单版本…</div>';
 (async()=>{try{orders=(await client.getImportedOrders()).orders;if(!alive)return;if(!orders.length){root.innerHTML='<section class="panel import-intro"><h2>还没有导入订单</h2><p>选择一份标准成本表和配套每日表，开始逐日查看利润。</p><a class="button primary" href="#import">导入 Excel</a></section>';return;}selected=orders.find(o=>o.id===orderId)||orders[0];revision=selected.revisionId;date=selected.start;revisions=(await client.getRevisions(selected.id)).revisions;await load();}catch(e){if(alive)root.innerHTML=`<section class="panel import-intro"><h2>本地服务不可用</h2><p>${esc(e.message)}</p><p>请关闭旧的服务窗口，再双击“启动网站.cmd”。</p></section>`;}})();
 return ()=>{alive=false;seq++;};
}
